import{_ as e,o as r,c as a,a as o}from"./chunks/plugin-vue_export-helper.F1EaaLXR.js";const g=JSON.parse('{"title":"CV","description":"Олег Сидоркин — инженер: 21 год в разработке, системы на Go и TypeScript, алго-трейдинг, RAG, self-hosted финансы и аудит архитектуры.","frontmatter":{"site":"pro","title":"CV","description":"Олег Сидоркин — инженер: 21 год в разработке, системы на Go и TypeScript, алго-трейдинг, RAG, self-hosted финансы и аудит архитектуры.","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/cv"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"CV"}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: 21 год в разработке, системы на Go и TypeScript, алго-трейдинг, RAG, self-hosted финансы и аудит архитектуры."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/cv"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"CV"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: 21 год в разработке, системы на Go и TypeScript, алго-трейдинг, RAG, self-hosted финансы и аудит архитектуры."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}]]},"headers":[],"relativePath":"cv.md","filePath":"cv.md"}'),n={name:"cv.md"};function i(l,t,d,s,c,h){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="cv" tabindex="-1">CV <a class="header-anchor" href="#cv" aria-label="Permalink to &quot;CV&quot;">​</a></h1><p>Инженер, 21 год в разработке. Строю системы и проверяю их как систему: метрика, режимы отказов, стоимость интеграции. Пишу код сам, поэтому совет не расходится с тем, что выполнимо руками.</p><h2 id="чем-занимаюсь" tabindex="-1">Чем занимаюсь <a class="header-anchor" href="#чем-занимаюсь" aria-label="Permalink to &quot;Чем занимаюсь&quot;">​</a></h2><ul><li><strong>AI-системы до продакшена.</strong> RAG с графом знаний, верификация фактов, прогон через открытые бенчмарки, а не по ощущению «вроде работает».</li><li><strong>Алго-трейдинг.</strong> Данные, признаки, ансамбль моделей, риск-гейты, ньюс-вето.</li><li><strong>Архитектура и производительность.</strong> Разбор платформ по шести доменам, дорожная карта и цена бездействия — см. <a href="/audit/">аудит</a>.</li><li><strong>Фронтенд и дизайн-системы.</strong> Корпоративные компоненты, low-code, миграции без остановки продукта.</li></ul><h2 id="избранные-проекты" tabindex="-1">Избранные проекты <a class="header-anchor" href="#избранные-проекты" aria-label="Permalink to &quot;Избранные проекты&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Проект</th><th>Что это</th><th>Доказательство</th></tr></thead><tbody><tr><td><strong>kb</strong></td><td>База знаний на GraphRAG: гибридный поиск, временной граф, слой верификации</td><td><a href="https://github.com/alterfo/kb" target="_blank" rel="noreferrer">github.com/alterfo/kb</a></td></tr><tr><td><strong>Approximate</strong></td><td>Алго-трейдер: Go, LightGBM + XGBoost, риск-гейты, Telegram-алерты</td><td><a href="https://github.com/alterfo/moex-trader" target="_blank" rel="noreferrer">moex-trader</a>, <a href="https://zenodo.org/records/24111519" target="_blank" rel="noreferrer">исследование AlgoPack и MOEX</a></td></tr><tr><td><strong>FinContext MCP</strong></td><td>Финансовый контекст для AI-ассистента бизнеса, self-hosted</td><td><a href="https://github.com/alterfo/fincontext-mcp" target="_blank" rel="noreferrer">fincontext-mcp</a></td></tr><tr><td><strong>Shelfprice</strong></td><td>Аудит ценников с локальной vision-моделью, экспорт в 1С</td><td>локальный проект</td></tr><tr><td><strong>IDEF0 Editor</strong></td><td>Редактор функциональных диаграмм по FIPS 183</td><td><a href="/idef0.html">/idef0</a>, <a href="/projects/idef0-editor.html">разбор</a></td></tr></tbody></table><h2 id="стек" tabindex="-1">Стек <a class="header-anchor" href="#стек" aria-label="Permalink to &quot;Стек&quot;">​</a></h2><p>Go, TypeScript, JavaScript, Vue 3, React, Node.js, Python для анализа данных. PostgreSQL, SQLite, Redis, Kafka, Yandex Cloud (Functions, API Gateway, YDB, Lockbox), Terraform, Docker. WebCrypto, IndexedDB, WebGPU, WASM.</p><h2 id="что-умею-доказать" tabindex="-1">Что умею доказать <a class="header-anchor" href="#что-умею-доказать" aria-label="Permalink to &quot;Что умею доказать&quot;">​</a></h2><ul><li>Публичные репозитории с тестами и CI, а не слайды.</li><li>Исследование по AlgoPack и MOEX с закрытыми «белыми пятнами» и рецензированием.</li><li>Восемь браузерных инструментов без сервера, с шифрованием на клиенте.</li></ul><h2 id="контакты" tabindex="-1">Контакты <a class="header-anchor" href="#контакты" aria-label="Permalink to &quot;Контакты&quot;">​</a></h2><p>Почта: <a href="mailto:osidorkin85@gmail.com" target="_blank" rel="noreferrer">osidorkin85@gmail.com</a> GitHub: <a href="https://github.com/alterfo" target="_blank" rel="noreferrer">github.com/alterfo</a> Telegram: <a href="https://t.me/jfyi_ps" target="_blank" rel="noreferrer">@jfyi_ps</a></p><p>Полное резюме с историей ролей — по запросу.</p>',13)])])}const m=e(n,[["render",i]]);export{g as __pageData,m as default};
